/* ------------------------------------------------------------------ 2. NFA */
const nfaT: Topic = {
  id: "cs.toc.nfa",
  title: "Non-determinism, ε-moves and the subset construction",
  blocks: [
    { type: "hook", text: "'The third symbol from the end is 1.' A DFA must remember the last three symbols, so it needs 8 states. An NFA needs 4: it simply guesses, at some 1, that this is the third-from-last and then checks the guess. Non-determinism is a design shortcut, not extra power." },
    { type: "objectives", items: ["Define an NFA and an ε-NFA, and decide acceptance by tracking sets of states.", "Compute ε-closures and run the subset construction.", "State and use the equivalence of NFAs and DFAs, and the exponential blow-up bound 2ⁿ.", "Know which operations NFAs make easy: union, concatenation, star, reversal."] },
    { type: "intuition", paras: ["An NFA may have several moves (or none) on a symbol. It accepts a string if some sequence of choices leads to an accepting state. Think of a parallel machine that splits at every choice; it accepts if any copy ends accepting. Nobody has to run the copies one by one: an equivalent deterministic machine keeps the set of states where the copies currently are.", "ε-moves add free jumps. They are the glue that lets us build machines for union, concatenation and star by wiring smaller machines together, which is exactly how the regular expression to automaton translation of the next topic works."] },
    { type: "definition", name: "NFA and ε-NFA", text: "N = (Q, Σ, δ, q₀, F) where:", items: ["δ : Q × (Σ ∪ {ε}) → 2^Q: a set of next states (possibly empty).", "ε-closure(S): all states reachable from S using only ε-moves (S itself included).", "Extended: δ̂(S, ε) = ε-closure(S) and δ̂(S, wa) = ε-closure( ⋃ over q ∈ δ̂(S, w) of δ(q, a) ).", "N accepts w iff δ̂({q₀}, w) contains an accepting state."] },
    { type: "definition", name: "Subset construction", text: "Given an NFA N with n states, the DFA D has:", items: ["States: sets of N-states (at most 2ⁿ, only the reachable ones are built).", "Start state: ε-closure({q₀}).", "δ_D(S, a) = ε-closure( ⋃ over q ∈ S of δ_N(q, a) ).", "Accepting states: every set that contains an accepting state of N.", "L(D) = L(N): so NFAs, ε-NFAs and DFAs accept exactly the regular languages."] },
    { type: "deep", sections: [
      { h: "Why the construction is correct", paras: ["By induction on |w|: the DFA state reached after reading w is exactly the set of all N-states reachable after w. The base is the ε-closure of the start state; the step applies one symbol and closes under ε. Acceptance in N means at least one reachable state is accepting, which is exactly 'the set contains an accepting state'."] },
      { h: "The blow-up is real", paras: ["The language Lₖ = 'the k-th symbol from the end is 1' has an NFA with k + 1 states, but every DFA for it needs 2ᵏ states: the DFA must remember the last k symbols, and two histories that differ in any of those symbols must be distinguishable. For k = 3 the NFA has 4 states and the subset construction produces exactly 8 reachable subsets. So 2ⁿ is a tight upper bound, not just a safe one."] },
      { h: "Removing ε-moves", paras: ["An ε-NFA can be converted to an NFA with the same states: new δ'(q, a) = ε-closure of ⋃ δ(p, a) over p ∈ ε-closure(q), and q becomes accepting if its closure contains an accepting state. This does not change the number of states."] },
      { h: "What non-determinism buys", paras: ["Each regular operation has a one-line ε-NFA gadget; complement is the exception."], points: ["Union: a new start state with ε-moves to both machines.", "Concatenation: ε-moves from the accepting states of the first to the start of the second.", "Star: a new start/accept state and ε-moves from every accepting state back to the start.", "Reversal: reverse every arrow, swap start and accepting states (a DFA reversed may become non-deterministic).", "Complement is hard for NFAs: swapping accepting states does not work; determinise first."] },
    ] },
    { type: "walkthrough", steps: ["Start with S₀ = ε-closure of the start state.", "For each unprocessed set S and each symbol a, compute the union of the a-moves of S, then close under ε.", "Name every new set as a DFA state; stop when no new set appears.", "Mark the sets that contain an accepting NFA state.", "Count the states: that is the size of the DFA (not necessarily minimal)."], prompt: { q: "An NFA has 4 states and no ε-moves. At most how many states does its subset-construction DFA have?", a: "2⁴ = 16 (every subset of the four states), though usually far fewer are reachable." } },
    { type: "figure", id: "nfa-tbl", for: "ex1", caption: "The NFA for 'third symbol from the end is 1': guess at a 1, then count two more symbols.", alt: "p loops on 0 and 1 and also goes to q on 1; q goes to r on 0 and 1; r goes to s on 0 and 1; s is accepting.", fig: { kind: "matrix", title: "δ of the 4-state NFA (start p, accept s)", cols: ["on 0", "on 1"], rows: [{ label: "p", cells: ["{p}", "{p, q}"], hl: true }, { label: "q", cells: ["{r}", "{r}"] }, { label: "r", cells: ["{s}", "{s}"] }, { label: "s (accept)", cells: ["∅", "∅"] }] } },
    { type: "figure", id: "nfa-run", for: "ex2", caption: "Running the NFA on 0110: the set of live states after each symbol.", alt: "Sets {p}, {p}, {p,q}, {p,q,r}, {p,r,s}; the last contains s.", fig: { kind: "strip", items: [{ label: "start", sub: "{p}", state: "done" }, { label: "0", sub: "{p}", state: "done" }, { label: "1", sub: "{p, q}", state: "done" }, { label: "1", sub: "{p, q, r}", state: "done" }, { label: "0", sub: "{p, r, s} accept", state: "now" }] } },
    { type: "example", id: "ex1", level: "gate", title: "Subset construction on the 4-state NFA", given: "The NFA above (start p, accept s).", find: "The number of reachable DFA states and accepting states.",
      steps: [{ say: "Start {p}. On 0: {p}. On 1: {p, q}." }, { say: "{p, q}: on 0 → {p, r}, on 1 → {p, q, r}." }, { say: "Continue: {p, r}, {p, q, r}, then {p, s}, {p, q, s}, {p, r, s}, {p, q, r, s}." }, { say: "That is every set that contains p: 2³ = 8 subsets. Exactly those that also contain s are accepting: 4 of them.", result: "8 states, 4 accepting" }],
      answer: "8 reachable DFA states, 4 accepting.", check: "Matches the bound 2ᵏ for k = 3: no DFA for this language can have fewer states." },
    { type: "example", id: "ex2", level: "gate", title: "Acceptance by tracking sets", given: "The same NFA; inputs 0110, 101, 000.", find: "Accept or reject.",
      steps: [{ say: "0110: {p} → {p} → {p, q} → {p, q, r} → {p, r, s}: contains s.", result: "accept (third from the end is 1)" }, { say: "101: {p} → {p, q} → {p, r} → {p, s}: contains s.", result: "accept" }, { say: "000: {p} → {p} → {p} → {p}: no s.", result: "reject" }],
      answer: "0110 and 101 accepted, 000 rejected.", check: "In 101 the third symbol from the end is the first symbol 1." },
    { type: "example", id: "ex3", level: "edge", title: "An ε-move changes the start state", given: "NFA with states 1 (start), 2, 3 (accepting), ε-move 1 → 2, and 2 --a--> 3.", find: "Is 'a' accepted? Is ε accepted?",
      steps: [{ say: "ε-closure({1}) = {1, 2}; this is where the machine really starts." }, { say: "Reading a: from 2 to 3: {3}, accepting.", result: "a is accepted" }, { say: "ε: the closure {1, 2} contains no accepting state.", result: "ε is rejected" }],
      answer: "a accepted, ε rejected.", check: "Forgetting the ε-closure of the start state would reject a." },
    { type: "lab", lab: "toc-nfa" },
    { type: "faded", title: "Your turn", given: "An NFA with 5 states and one ε-move has an equivalent DFA.", steps: [{ say: "Upper bound on its reachable DFA states?", blank: true, answer: "2⁵ = 32 subsets." }, { say: "Does removing the ε-move change the number of NFA states?", blank: true, answer: "No: the ε-free NFA has the same 5 states." }] },
    { type: "trap", wrong: "NFAs accept more languages than DFAs.", tempting: "Guessing sounds more powerful.", whyWrong: "The subset construction turns any NFA into a DFA for the same language.", rule: "NFA = DFA in power; they differ in size, not in the languages they accept." },
    { type: "trap", wrong: "Swapping accepting states complements an NFA.", tempting: "It works for a DFA.", whyWrong: "A string may have both accepting and rejecting runs; after the swap it still has an accepting one.", rule: "Determinise before complementing." },
    { type: "trap", wrong: "The DFA from the subset construction always has 2ⁿ states.", tempting: "2ⁿ is the bound.", whyWrong: "Only reachable subsets are built, often far fewer.", rule: "2ⁿ is an upper bound for n NFA states; the reachable count is what you compute." },
    { type: "shortcut", text: "'The k-th symbol from the end is a' has an (k + 1)-state NFA and a minimal DFA with exactly 2ᵏ states. Use it for any question asking the DFA size of such a language.", validWhen: "Binary alphabet and a fixed symbol at a fixed distance from the end." },
    { type: "gate", text: "GATE asks the number of states of the DFA obtained from an NFA by the subset construction, whether an NFA accepts a given string, equivalence of NFA and DFA, and the NFA/DFA size gap for 'k-th from the end'." },
    { type: "recall", cards: [{ q: "NFA transition type", a: "δ : Q × (Σ ∪ {ε}) → 2^Q" }, { q: "ε-closure(S)", a: "States reachable from S by ε-moves only" }, { q: "Subset construction size", a: "At most 2ⁿ states" }, { q: "NFA and DFA power", a: "Equal: both accept exactly the regular languages" }, { q: "Complementing an NFA", a: "Determinise first" }] },
    { type: "check", questions: [
      { id: "tn1", kind: "NAT", marks: 1, q: "An NFA with 6 states and no ε-moves is converted to a DFA by the subset construction. The maximum number of DFA states is", answer: "64", solution: "2⁶." },
      { id: "tn2", kind: "NAT", marks: 2, q: "For the 4-state NFA for 'the third symbol from the end is 1', the number of reachable states in the subset construction is", answer: "8", solution: "Every subset that contains p." },
      { id: "tn3", kind: "MCQ", marks: 1, q: "Which statement is true?", options: ["Every NFA language is regular", "Some NFA language is not regular", "NFAs are strictly more powerful than DFAs", "ε-moves allow non-regular languages"], answer: "A", solution: "NFA = ε-NFA = DFA in power." },
      { id: "tn4", kind: "MSQ", marks: 2, q: "Which are true for the NFA for 'third symbol from the end is 1'?", options: ["It accepts 0100", "It accepts 1000", "It accepts 101", "A minimal DFA for the language has 8 states"], answer: "A, C, D", solution: "1000 has third-from-last symbol 0." },
      { id: "tn5", kind: "MCQ", marks: 2, q: "ε-closure({1}) in an NFA with ε-moves 1 → 2 and 2 → 3 is", options: ["{1}", "{1, 2}", "{1, 2, 3}", "{2, 3}"], answer: "C", solution: "Closure includes the set itself and everything reachable by ε-moves." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Theory of Computation", sub: "NFA, DFA and conversions", href: TP }, { label: "Topic 1: DFAs", sub: "The deterministic machine", href: "/study/finite-automata" }, { label: "Topic 3: regular expressions", sub: "From expressions to machines", href: "/study/finite-automata" }] },
    { type: "links", prereq: ["DFA", "Power set"], usedIn: ["Regex engines", "Model checking"], cross: ["CD: lexical analysis"] },
  ],
};

/* ------------------------------------------------------------------ 3. Regular expressions */
const rxT: Topic = {
  id: "cs.toc.regex",
  title: "Regular expressions and Kleene's theorem",
  blocks: [
    { type: "hook", text: "grep, lex and every search box that accepts a pattern run a regular expression through the machinery of this chapter. Kleene's theorem is the guarantee behind them: expressions and finite automata describe exactly the same languages." },
    { type: "objectives", items: ["Write and read regular expressions with the correct precedence.", "Convert an expression to an ε-NFA by Thompson's construction and count its states.", "Convert an automaton back to an expression by state elimination.", "Use the algebraic identities to simplify and compare expressions."] },
    { type: "intuition", paras: ["A regular expression is a formula for a language, built from three operations: union (a|b), concatenation (ab) and star (a*, zero or more repetitions). The base cases are single symbols, ε and ∅. Every regular language has such a formula, and every such formula is a regular language: that is Kleene's theorem.", "Each operation has a matching automaton gadget, which is why the theorem is constructive: for union put two machines in parallel, for concatenation chain them, for star loop one back on itself. The ε-moves of the previous topic are the wiring."] },
    { type: "definition", name: "Regular expressions", text: "Over alphabet Σ, the expressions and their languages are defined by induction:", items: ["∅ denotes {}; ε denotes {ε}; a ∈ Σ denotes {a}.", "(r | s) denotes L(r) ∪ L(s).", "(rs) denotes L(r)L(s); r* denotes L(r)*.", "Precedence: star binds tightest, then concatenation, then union. So ab*|c means (a(b*)) | c.", "Shorthand: r⁺ = rr*, r? = (r | ε)."] },
    { type: "definition", name: "Kleene's theorem", text: "A language is regular (accepted by a DFA) iff it is described by a regular expression.", items: ["Expression → automaton: Thompson's construction gives an ε-NFA with one start and one accepting state, linear in the size of the expression.", "Automaton → expression: state elimination (GNFA) or the Arden/recurrence method.", "Corollary: regular languages are closed under union, concatenation, star, complement, intersection and reversal."] },
    { type: "deep", sections: [
      { h: "Thompson's construction", paras: ["Every sub-expression becomes a small ε-NFA with a fresh start state s and a fresh accept state f. A symbol a: s --a--> f. Union r|s': new start with ε-moves into both machines and ε-moves from both accept states to a new accept. Concatenation: ε from the accept of the first to the start of the second. Star: ε from s to f (zero repetitions), ε into the machine, ε from its accept back to its start (repeat) and out to f.", "Counting states depends on the variant. With a fresh start and accept state for every operator, a has 2 states, ab has 6, a* has 4, a|b has 6, (ab)* has 8, a(b|c)* has 12 and (a|b)*abb has 20. Variants that merge the joint states give fewer (ab becomes 4); always read which variant a question uses, but the size is always linear in the length of the expression."] },
      { h: "State elimination", paras: ["Add a new start and a new accept state, then remove the original states one at a time. To remove q, for every pair (p, r) with arrows p → q and q → r, add the label p→q · (loop of q)* · q→r to the arrow p → r (union with an existing p → r label). When only the new start and accept state remain, the label between them is the regular expression."] },
      { h: "Algebra of expressions", paras: ["These identities let you simplify an expression or show two expressions are equal; each can be checked by comparing the languages."], points: ["r|s = s|r, (r|s)|t = r|(s|t), r|r = r, r|∅ = r.", "rε = εr = r, r∅ = ∅r = ∅, (rs)t = r(st); concatenation does not commute.", "r(s|t) = rs|rt and (r|s)t = rt|st (distribution).", "(r*)* = r*, ε* = ∅* = ε, r*r* = r*, rr* = r*r = r⁺.", "(r|s)* = (r*s*)* = (r*|s*)* , but (rs)* ≠ r*s* in general."] },
      { h: "Arden's rule", paras: ["If X = RX | S and ε ∉ L(R), then the unique solution is X = R*S. Writing one equation per state of a DFA (state = union of 'symbol then next state', plus ε for accepting states) and solving them with Arden's rule gives the expression for the start state."] },
    ] },
    { type: "walkthrough", steps: ["Parse the expression with the precedence rules; draw the parse tree.", "Build a gadget for each leaf, then combine bottom-up.", "Count states: each operator adds the fixed number of new states for its gadget.", "To go back, eliminate the non-start, non-accept states one by one, composing labels.", "Check the result on a few short strings, listing the language up to length 3."], prompt: { q: "List the strings of length at most 3 in (0|1)*01.", a: "01, 001 and 101: strings that end in 01 (the shortest is 01)." } },
    { type: "figure", id: "thompson-tbl", for: "ex1", caption: "States in Thompson's construction (fresh start and accept state for every operator).", alt: "a has 2 states, ab 6, a* 4, a|b 6, (ab)* 8, a(b|c)* 12, (a|b)*abb 20.", fig: { kind: "matrix", title: "State counts", cols: ["states"], rows: [{ label: "a", cells: [2] }, { label: "a*", cells: [4] }, { label: "a | b", cells: [6] }, { label: "ab", cells: [6] }, { label: "(ab)*", cells: [8] }, { label: "a(b|c)*", cells: [12] }, { label: "(a|b)*abb", cells: [20], hl: true }] } },
    { type: "figure", id: "lang-strip", for: "ex2", caption: "Languages up to length 3.", alt: "(0|1)*01 gives 01, 001, 101; 0*1 gives 1, 01, 001; 1(0|1)*0 gives 10, 100, 110.", fig: { kind: "strip", items: [{ label: "(0|1)*01", sub: "01, 001, 101", state: "done" }, { label: "0*1", sub: "1, 01, 001", state: "done" }, { label: "1(0|1)*0", sub: "10, 100, 110", state: "done" }, { label: "(01)*", sub: "ε, 01, 0101 (≤ 4)", state: "now" }] } },
    { type: "example", id: "ex1", level: "gate", title: "Counting Thompson states", given: "The expression (a|b)*abb, with a fresh start and accept state for every operator.", find: "The number of states of the ε-NFA.",
      steps: [{ say: "Leaves: a, b, a, b, b: 5 leaves × 2 states = 10 states." }, { say: "a|b adds 2 (new start and accept), the star adds 2: 4 more." }, { say: "Three concatenations (between (a|b)*, a, b, b) add 2 each: 6 more.", result: "10 + 4 + 6 = 20" }],
      answer: "20 states, of which 1 start and 1 accept.", check: "Equals the verified table: linear in the expression, 20 for 8 symbols and operators." },
    { type: "example", id: "ex2", level: "gate", title: "Reading a language off an expression", given: "r = (0|1)*01 and s = 0*1.", find: "Strings of length ≤ 3 in each, and whether 101 ∈ L(s).",
      steps: [{ say: "r: any string followed by 01: 01, 001, 101 (length ≤ 3)." }, { say: "s: zero or more 0s then a single 1: 1, 01, 001." }, { say: "101 has a 1 before the last 1; 0*1 allows only zeros before the single 1.", result: "101 ∉ L(s)" }],
      answer: "r gives 01, 001, 101; s gives 1, 01, 001; 101 ∉ L(s).", check: "L(s) ⊂ L(0*1(0|1)*) but s itself allows exactly one 1." },
    { type: "example", id: "ex3", level: "edge", title: "Two expressions, one language?", given: "(a|b)* and (a*b*)*.", find: "Are they equal?",
      steps: [{ say: "(a*b*)* ⊆ (a|b)*: every string built from a's and b's." }, { say: "Conversely any string over {a, b} is a concatenation of single symbols, each in a*b* (one a or one b): so (a|b)* ⊆ (a*b*)*.", result: "equal" }],
      answer: "Equal; but (ab)* ≠ a*b*: abab ∈ (ab)* and abab ∉ a*b*.", check: "Test the shortest string that separates them: abab." },
    { type: "lab", lab: "toc-regex" },
    { type: "faded", title: "Your turn", given: "Write a regular expression for 'binary strings with an even number of 1s'.", steps: [{ say: "Group by 1s: each pair of 1s is separated by 0s.", blank: true, answer: "0*(10*10*)*" }, { say: "Does it accept ε and 0?", blank: true, answer: "Yes to both: zero repetitions of the group." }] },
    { type: "trap", wrong: "(ab)* = a*b*.", tempting: "Star seems to distribute over concatenation.", whyWrong: "(ab)* repeats the pair ab together; a*b* is all a's then all b's.", rule: "(rs)* ≠ r*s* in general; (r*s*)* = (r|s)* is the true identity." },
    { type: "trap", wrong: "ab|c means a(b|c).", tempting: "Reading left to right.", whyWrong: "Concatenation binds tighter than union: ab|c = (ab)|c.", rule: "Star, then concatenation, then union." },
    { type: "trap", wrong: "∅* = ∅.", tempting: "Star of nothing is nothing.", whyWrong: "L* always contains ε (zero repetitions), so ∅* = {ε}.", rule: "∅* = ε* = ε." },
    { type: "shortcut", text: "Thompson state count with fresh states per operator: 2 per leaf + 2 per union + 2 per star + 2 per concatenation. For an expression with ℓ symbols, u unions, s stars and c concatenations the count is 2(ℓ + u + s + c).", validWhen: "The question uses that variant (every operator creates fresh start and accept states); other variants merge states." },
    { type: "gate", text: "GATE asks whether two expressions denote the same language, the language described by an expression, the expression for a described language, the number of states of an NFA built from an expression, and state elimination on a small automaton." },
    { type: "recall", cards: [{ q: "Precedence", a: "Star > concatenation > union" }, { q: "Kleene's theorem", a: "Regular expressions = finite automata" }, { q: "Arden's rule", a: "X = RX | S with ε ∉ R gives X = R*S" }, { q: "∅*", a: "ε" }, { q: "(r|s)*", a: "(r*s*)* = (r*|s*)*" }] },
    { type: "check", questions: [
      { id: "tr1", kind: "NAT", marks: 1, q: "How many strings of length exactly 2 are in (0|1)*01?", answer: "1", solution: "Only 01." },
      { id: "tr2", kind: "NAT", marks: 2, q: "With a fresh start and accept state for every operator, the Thompson ε-NFA for (ab)* has how many states?", answer: "8", solution: "Leaves a, b: 4; concatenation +2; star +2." },
      { id: "tr3", kind: "MCQ", marks: 1, q: "Which pair is NOT equal?", options: ["(a|b)* and (a*b*)*", "a(ba)* and (ab)*a", "(ab)* and a*b*", "ε* and ∅*"], answer: "C", solution: "abab ∈ (ab)* but ∉ a*b*." },
      { id: "tr4", kind: "MSQ", marks: 2, q: "Which strings are in 0*10*?", options: ["1", "0100", "11", "0001"], answer: "A, B, D", solution: "Exactly one 1; 11 has two." },
      { id: "tr5", kind: "MCQ", marks: 2, q: "Solving X = 0X | 1 for the start state with Arden's rule gives", options: ["0*1", "01*", "(0|1)*", "0*|1"], answer: "A", solution: "R = 0, S = 1: X = R*S = 0*1." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Theory of Computation", sub: "Regular expressions", href: TP }, { label: "Topic 2: NFA", sub: "The machines expressions compile to", href: "/study/finite-automata" }, { label: "Compiler Design", sub: "Lexical analysis", href: "/topics/compiler-design" }] },
    { type: "links", prereq: ["NFA and ε-moves"], usedIn: ["Lexers, grep, input validation"], cross: ["CD: tokens and patterns"] },
  ],
};

/* ------------------------------------------------------------------ 4. Minimisation */
const minT: Topic = {
  id: "cs.toc.min",
  title: "DFA minimisation and the Myhill–Nerode theorem",
  blocks: [
    { type: "hook", text: "Two DFAs can accept the same language yet one has seven states and the other three. Every regular language has a unique smallest DFA, and a simple procedure finds it. The same idea also tells you when a language is not regular." },
    { type: "objectives", items: ["Remove unreachable states and merge indistinguishable ones.", "Run partition refinement and the table-filling algorithm by hand.", "State the Myhill–Nerode theorem and use it for the number of states of a minimal DFA.", "Use distinguishing suffixes to prove a lower bound on states."] },
    { type: "intuition", paras: ["Two states are the same if no future input can tell them apart: for every string w, either both lead to acceptance or both lead to rejection. Machines carry redundancy in two ways: states that can never be reached, and states that behave identically. Strip both and what is left is the minimal DFA, and it is unique up to renaming states.", "This is also the theory behind 'how many states does a DFA for L need?'. Each distinct future-behaviour class of prefixes needs its own state, so the number of classes is exactly the size of the smallest DFA, and if the number of classes is infinite the language is not regular."] },
    { type: "definition", name: "Distinguishability and Myhill–Nerode", text: "For a language L over Σ:", items: ["States p and q of a DFA are distinguishable if some string w makes exactly one of δ̂(p, w), δ̂(q, w) accepting; otherwise equivalent.", "Prefixes x and y are L-equivalent (x ≡ y) iff for every z, xz ∈ L ⇔ yz ∈ L.", "Myhill–Nerode: L is regular iff ≡_L has finitely many classes, and then the number of classes equals the number of states of the minimal complete DFA.", "The minimal DFA is unique up to isomorphism."] },
    { type: "deep", sections: [
      { h: "Partition refinement", paras: ["Remove unreachable states. Split the rest into accepting and non-accepting: this separates every pair distinguishable by ε. Then repeat: two states stay together only if, for every symbol, their successors lie in the same block; split blocks that violate this. Stop when no block splits. The blocks are the states of the minimal DFA. Each round uses one more symbol of the distinguishing string, so at most |Q| rounds are needed.", "Hopcroft's algorithm performs the same refinement cleverly in O(|Σ| n log n) time; for GATE, doing it by hand on at most 8 states is what matters."] },
      { h: "Table filling", paras: ["Make a triangular table of all unordered pairs. Mark every pair with exactly one accepting state. Repeatedly mark a pair (p, q) if for some symbol a the pair (δ(p, a), δ(q, a)) is already marked. When nothing changes, the unmarked pairs are equivalent and can be merged. Counting the unmarked-pair classes gives the minimal state count."] },
      { h: "Lower bounds by distinguishing suffixes", paras: ["To show a DFA needs at least k states, exhibit k prefixes x₁ … x_k and, for every pair, a suffix z such that exactly one of x_i z, x_j z is in L. Example: for 'ends with 01', the prefixes ε, 0, 01 are pairwise distinguished by the suffixes 1 (ε·1 = 1 ∉ L, 0·1 ∈ L) and ε (01 ∈ L, the others ∉ L). So at least 3 states."] },
      { h: "Using it to prove non-regularity", paras: ["If infinitely many prefixes are pairwise distinguishable, no DFA can have a state for each, so L is not regular. For aⁿbⁿ the prefixes a, aa, aaa, … are pairwise distinguished by suffixes bⁱ: so infinitely many classes. The pumping lemma of the next chapter reaches the same conclusion differently."] },
    ] },
    { type: "walkthrough", steps: ["Delete states unreachable from the start state.", "Split into accepting and non-accepting.", "For each block and each symbol, group the states by which blocks their successors fall in.", "Replace the partition by these finer groups and repeat until it no longer changes.", "Each block becomes one state; transitions are inherited from any member; the start block contains the old start state."], prompt: { q: "A DFA has 5 states, 2 accepting. What is the maximum number of states of its minimal DFA?", a: "5, if all are reachable and pairwise distinguishable." } },
    { type: "figure", id: "dfa7", for: "ex1", caption: "A 7-state DFA over {0, 1} (start A, accepting C and D).", alt: "A on 0 goes to B and on 1 to C; B to A and D; C to E and F; D to E and F; E to E and F; F to F and F; G to G and A.", fig: { kind: "matrix", title: "δ (start A, accepting C, D; G is not reachable)", cols: ["on 0", "on 1"], rows: [{ label: "A", cells: ["B", "C"], hl: true }, { label: "B", cells: ["A", "D"] }, { label: "C (accept)", cells: ["E", "F"] }, { label: "D (accept)", cells: ["E", "F"] }, { label: "E", cells: ["E", "F"] }, { label: "F", cells: ["F", "F"] }, { label: "G", cells: ["G", "A"], dim: true }] } },
    { type: "figure", id: "refine", for: "ex1", caption: "The refinement: unreachable state dropped, then two splits.", alt: "Round 0: {C, D} and {A, B, E, F}. Round 1: {C, D}, {A, B}, {E, F}.", fig: { kind: "steps", frames: [{ caption: "Drop G; split by acceptance: {C, D} | {A, B, E, F}.", fig: { kind: "strip", items: [{ label: "{C, D}", sub: "accepting", state: "done" }, { label: "{A, B, E, F}", sub: "non-accepting", state: "now" }] } }, { caption: "A, B go to accepting blocks on some symbol; E, F do not: split.", fig: { kind: "strip", items: [{ label: "{C, D}", sub: "state 1", state: "done" }, { label: "{A, B}", sub: "state 2", state: "done" }, { label: "{E, F}", sub: "state 3", state: "done" }] } }] } },
    { type: "example", id: "ex1", level: "gate", title: "Minimise a 7-state DFA", given: "The DFA in the table (start A, accepting C, D).", find: "The number of states of the minimal DFA and which states merge.",
      steps: [{ say: "G cannot be reached from A: remove it." }, { say: "Split by acceptance: {C, D} and {A, B, E, F}." }, { say: "Refine {A, B, E, F}: A goes to C on 1 and B goes to D on 1 (both in the accepting block), but E and F go to F (non-accepting). So {A, B} and {E, F} separate." }, { say: "Check {A, B}: on 0 both go inside {A, B}; on 1 both into {C, D}. {E, F}: on 0 inside {E, F}, on 1 into F. {C, D}: on 0 into E, on 1 into F: identical.", result: "3 blocks: {C, D}, {A, B}, {E, F}" }],
      answer: "3 states, after removing G and merging C with D, A with B and E with F.", check: "The minimal DFA accepts the strings that end in an accepting block after the partition; the count 3 is stable under a further round." },
    { type: "example", id: "ex2", level: "gate", title: "Minimal DFA size for 'ends with 01'", given: "L = binary strings ending with 01.", find: "The number of Myhill–Nerode classes.",
      steps: [{ say: "Classes by the longest suffix that is a prefix of 01: [ε, 1, …], [ends in 0], [ends in 01]." }, { say: "Distinguish them: suffix 1 separates 'ends in 0' (becomes 01, accepted) from 'no suffix' (becomes 1, rejected); suffix ε separates 'ends in 01'." }, { say: "No more classes: every prefix falls in one of these three.", result: "3 classes" }],
      answer: "3 states.", check: "Agrees with the |01| + 1 rule and the 3-state DFA of topic 1." },
    { type: "example", id: "ex3", level: "edge", title: "A product DFA that is not minimal", given: "Product of 'ends in 0' (2 states) and 'ends in 0' (2 states), intersection.", find: "States before and after minimisation.",
      steps: [{ say: "The product has 2 × 2 = 4 states." }, { say: "The pairs (reading the same string) are always (x, x): only (not-0, not-0) and (0, 0) are reachable, and only 2 of the 4 are reachable.", result: "2 reachable, equivalent to the single condition" }],
      answer: "4 states before; 2 after removing unreachable states.", check: "Intersecting a language with itself gives itself; the minimal DFA is that of 'ends in 0'." },
    { type: "lab", lab: "toc-min" },
    { type: "faded", title: "Your turn", given: "DFA with 4 states A, B, C, D; accepting {D}; A,B on a → B, C; C on a → D; D on a → D.", steps: [{ say: "First split by acceptance.", blank: true, answer: "{D} | {A, B, C}" }, { say: "Do A, B, C stay together?", blank: true, answer: "No: C goes to D on a, but A and B go into {A, B, C}. Split C off, then check A and B." }] },
    { type: "trap", wrong: "Merge any two states that have the same transitions.", tempting: "Identical rows look identical.", whyWrong: "The rows may point to states that are themselves distinguishable; equality of rows is only meaningful after the partition has stabilised.", rule: "Merge by partition refinement, not by comparing rows once." },
    { type: "trap", wrong: "The minimal DFA is the same as the minimal NFA.", tempting: "Both are 'the smallest machine'.", whyWrong: "Minimal DFAs are unique; minimal NFAs are not, and can be exponentially smaller.", rule: "Minimisation theory is for DFAs." },
    { type: "trap", wrong: "Forgetting to remove unreachable states first.", tempting: "They look like ordinary non-accepting states.", whyWrong: "An unreachable state may be distinguishable from reachable ones and inflate the count.", rule: "Always delete unreachable states before refining." },
    { type: "shortcut", text: "Number of states of the minimal DFA = number of Myhill–Nerode classes. Binary 'divisible by m': write m = 2ᵏ·j with j odd; the minimal DFA has j + k states (3 → 3, 4 → 3, 5 → 5, 6 → 4, 8 → 4, 12 → 5). 'Ends with w' over {0, 1} needs |w| + 1.", validWhen: "You can list the classes and a distinguishing suffix for every pair." },
    { type: "gate", text: "GATE asks the number of states of the minimal DFA for a described language or a drawn DFA, whether two DFAs are equivalent, and (with the next chapter) uses Myhill–Nerode reasoning to prove a language is not regular." },
    { type: "recall", cards: [{ q: "Distinguishable states", a: "Some string leads exactly one of them to acceptance" }, { q: "Myhill–Nerode", a: "Regular iff finitely many classes; classes = states of the minimal DFA" }, { q: "First split", a: "Accepting versus non-accepting, after removing unreachable states" }, { q: "Hopcroft", a: "O(|Σ| n log n) minimisation" }, { q: "Uniqueness", a: "The minimal DFA is unique up to renaming of states" }] },
    { type: "check", questions: [
      { id: "tm1", kind: "NAT", marks: 1, q: "The 7-state DFA in this lesson has how many states after minimisation?", answer: "3", solution: "{C, D}, {A, B}, {E, F}; G is removed." },
      { id: "tm2", kind: "NAT", marks: 2, q: "A DFA for 'binary value divisible by 5' is minimal. How many states does it have?", answer: "5", solution: "The 5 remainders are pairwise distinguishable." },
      { id: "tm3", kind: "MCQ", marks: 1, q: "By Myhill–Nerode, a language with infinitely many equivalence classes is", options: ["Regular", "Not regular", "Finite", "Accepted by a DFA with a dead state"], answer: "B", solution: "A DFA would need infinitely many states." },
      { id: "tm4", kind: "MSQ", marks: 2, q: "Which are true?", options: ["Unreachable states can be removed without changing the language", "The minimal DFA of a regular language is unique up to renaming", "The minimal NFA of a regular language is unique", "Two equivalent states have identical transition rows in the minimal DFA"], answer: "A, B", solution: "Minimal NFAs are not unique; in the minimal DFA no two states are equivalent." },
      { id: "tm5", kind: "MCQ", marks: 2, q: "The 6-state DFA 'binary value mod 6 = 0' (one state per remainder) is minimised. The minimal DFA has", options: ["2", "3", "4", "6"], answer: "C", solution: "6 = 2 × 3: divisible by 6 means divisible by 3 and last bit 0. Remainders 0 and 3 cannot be told apart by any suffix once the last bit is known, and so on: m = 2ᵏ·j with j odd needs j + k states, here 3 + 1 = 4 (verified by partition refinement)." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Theory of Computation", sub: "Minimal DFA", href: TP }, { label: "Topic 1: DFAs", sub: "Designing machines", href: "/study/finite-automata" }, { label: "Chapter 2: closure and pumping lemma", sub: "Proving a language is not regular", href: TP }] },
    { type: "links", prereq: ["DFA", "Equivalence relations"], usedIn: ["Hardware state minimisation", "Lexer generators"], cross: ["DL: state reduction"] },
  ],
};

